  static MetricsBatch decMetricsBatch(Dec d) {
    MetricsBatch r = new MetricsBatch();
    while (!d.done()) {
      int t = d.readTag();
      switch (t) {
        case 10:
          r.id = d.readString();
          break;
        case 18: {   // the packed form
          int outer = d.push();
          long[] acc = new long[8];
          int n = 0;
          while (!d.done()) {
            if (n == acc.length) acc = java.util.Arrays.copyOf(acc, n * 2);
            acc[n++] = d.readVarint();
          }
          d.pop(outer);
          r.ticks = append(r.ticks, acc, n);
          break;
        }
        case 16: {   // the same field, written unpacked: legal wire
          long[] one = {d.readVarint()};
          r.ticks = append(r.ticks, one, 1);
          break;
        }
        case 26: {   // the packed form
          int outer = d.push();
          double[] acc = new double[8];
          int n = 0;
          while (!d.done()) {
            if (n == acc.length) acc = java.util.Arrays.copyOf(acc, n * 2);
            acc[n++] = d.readDouble();
          }
          d.pop(outer);
          r.values = append(r.values, acc, n);
          break;
        }
        case 25: {   // the same field, written unpacked: legal wire
          double[] one = {d.readDouble()};
          r.values = append(r.values, one, 1);
          break;
        }
        case 34: {   // the packed form
          int outer = d.push();
          int[] acc = new int[8];
          int n = 0;
          while (!d.done()) {
            if (n == acc.length) acc = java.util.Arrays.copyOf(acc, n * 2);
            acc[n++] = (int) d.readVarint();
          }
          d.pop(outer);
          r.codes = append(r.codes, acc, n);
          break;
        }
        case 32: {   // the same field, written unpacked: legal wire
          int[] one = {(int) d.readVarint()};
          r.codes = append(r.codes, one, 1);
          break;
        }
        case 42: {   // the packed form
          int outer = d.push();
          boolean[] acc = new boolean[8];
          int n = 0;
          while (!d.done()) {
            if (n == acc.length) acc = java.util.Arrays.copyOf(acc, n * 2);
            acc[n++] = d.readVarint() != 0;
          }
          d.pop(outer);
          r.flags = append(r.flags, acc, n);
          break;
        }
        case 40: {   // the same field, written unpacked: legal wire
          boolean[] one = {d.readVarint() != 0};
          r.flags = append(r.flags, one, 1);
          break;
        }
        case 50: {   // the packed form
          int outer = d.push();
          int[] acc = new int[8];
          int n = 0;
          while (!d.done()) {
            if (n == acc.length) acc = java.util.Arrays.copyOf(acc, n * 2);
            acc[n++] = (int) d.readVarint();
          }
          d.pop(outer);
          r.statuses = append(r.statuses, acc, n);
          break;
        }
        case 48: {   // the same field, written unpacked: legal wire
          int[] one = {(int) d.readVarint()};
          r.statuses = append(r.statuses, one, 1);
          break;
        }
        default:
          d.skip(t);
          break;
      }
    }
    return r;
  }

